function SumOfProperDivisors(n)
    if n le 1 then return 0; end if;
    sum := 1;
    d := 2;
    while d * d le n do
        if n mod d eq 0 then
            sum +:= d;
            complement := n div d;
            if d ne complement then
                sum +:= complement;
            end if;
        end if;
        d +:= 1;
    end while;
    return sum;
end function;

