sumProperDivisors := function(n)
    if n le 1 then
        return 0;
    end if;
    sum := 1; // 1 is always a proper divisor for n > 1
    for i := 2 to Isqrt(n) do
        if n mod i eq 0 then
            sum := sum + i;
            if i ne n div i then
                sum := sum + (n div i);
            end if;
        end if;
    end for;
    return sum;
end function;

